head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
scwin.gIsurCd;
scwin.mode = "I";
scwin.key_row = '';
scwin.vScrenID = 'ULDSTF10806.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_init = function() {
    if (scwin.gDepCd != '5B10') {
        $c.stf.showObj(btn_Input, false);
    }
};
scwin.fn_Input = async function() {
    scwin.mode = "I";
    scwin.key_row = '';
    await $c.frame.CreateDialogFrame("ONLINE", "/dsclproc/ULDSTF10807.gfm", "전화통보 입력", 50, 10, 845, 495, "window");
};
scwin.fn_SetCode = function() {
    scwin.gDepCd = js_dep_cd;

    //사이버정보분석팀일경우 팀코드가 시장마다 다르기 때문에 상위부서코드로 넣어준다. 20240510
    if (scwin.gDepCd.substring(0, 2) == '5B') {
        scwin.gDepCd = '5B10';
    }
    scwin.gEmpNo = js_emp_no;
    scwin.gLdMktTp = js_market;

    //  기간 from~ to  셋팅	
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_FromDate.setValue($c.ut.cGetMinusDate2(vCurDate, 365)); // 일주일전 날짜
    edt_ToDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

};
scwin.fn_Search = function() {
    var duty_yn = "N";
    if (js_duty == "Y" || js_duty_chrg == "Y") {
        duty_yn = "Y";
    }
    var url = "/OnlineNotice.do?method=listOnlineNotice" + "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd) + "&ONLN_NOTI_YN=N" + "&DEP_CD=" + scwin.gDepCd + "&LD_MKT_TP_CD=" + scwin.gLdMktTp + "&SDATE=" + $c.stf.getObjectValue(edt_FromDate) + "&EDATE=" + $c.stf.getObjectValue(edt_ToDate) + "&DUTY_YN=" + duty_yn + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Grid.DataID = encodeURI(url);
    dts_Grid.reset();
    $c.cm.ShowWin(grd_Grid);
};
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    noti_yn = dts_Grid.getCellData(row, "NOTI_YN");
    var popup_height = "";
    if (scwin.gDepCd == '5B10') {
        popup_height = "495";
    } else {
        popup_height = "455";
    }
    if (colid == 'COM_ABBRV') {
        scwin.gIsurCd = dts_Grid.getCellData(row, "ISUR_CD");
        scwin.gIsurCd = scwin.gIsurCd.substring(0, 5);
        $c.stf.fn_PopupCorpInfo();
    } else {
        if (noti_yn == 'Y') {
            scwin.key_row = row;
            await $c.frame.CreateDialogFrame("search", "/dsclproc/ULDSTF10807.gfm", "전화통보결과 조회", 100, 50, 845, popup_height, "window");
        } else {
            scwin.mode = "U";
            scwin.key_row = row;
            await $c.frame.CreateDialogFrame("input", "/dsclproc/ULDSTF10807.gfm", "전화통보 입력", 100, 50, 845, popup_height, "window");
        }
    }
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.img_FromCal_onclick = function() {
    popUpCalendar2(edt_FromDate);
};
scwin.img_ToCal_onclick = function() {
    popUpCalendar2(edt_ToDate);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_FromDate, edt_ToDate);
};
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    if (dts_Grid.errorMsg) {
        $c.win.alert(dts_Grid.errorMsg);
    } else {
        $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    }
    $c.cm.CloseWin(rowcount, grd_Grid);
};
scwin.dts_Grid_OnLoadError = function() {
    $c.stf.alert_error(dts_Grid);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else return true;
};
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.btn_Input_onclick = function() {
    scwin.fn_Input();
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.libRoundPanel.PanelToGroupBox(panel_1);
    scwin.fn_SetCode();
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    scwin.fn_init();
    scwin.fn_Search();
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_Grid, '전화통보', '', 8);
};
